import{_ as e,c as a,o as r,af as l,al as n,am as s,an as o}from"./chunks/framework.4G89wRmb.js";const y=JSON.parse('{"title":"南武联合党","description":"","frontmatter":{},"headers":[],"relativePath":"databank/settings/main/nambu_rengoist_party.md","filePath":"databank/settings/main/nambu_rengoist_party.md"}'),i={name:"databank/settings/main/nambu_rengoist_party.md"};function d(h,t,g,m,f,_){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="南武联合党" tabindex="-1">南武联合党 <a class="header-anchor" href="#南武联合党" aria-label="Permalink to “南武联合党”">​</a></h1><p><strong>南武联合党</strong>（Nambu United Party），是<a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>的创始者、领导核心与唯一执政党。</p><h2 id="基本情报" tabindex="-1">基本情报 <a class="header-anchor" href="#基本情报" aria-label="Permalink to “基本情报”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>党徽</strong></td><td style="text-align:left;"><img src="'+n+'" alt="党徽"></td></tr><tr><td style="text-align:left;"><strong>党旗</strong></td><td style="text-align:left;"><img src="'+s+'" alt="党旗-正式">（正式）或 <img src="'+o+'" alt="党旗-游行用">（游行）</td></tr><tr><td style="text-align:left;"><strong>最高领导机构</strong></td><td style="text-align:left;"><a href="./supreme_peoples_committee.html">南武最高人民委员会</a></td></tr><tr><td style="text-align:left;"><strong>创始人</strong></td><td style="text-align:left;"><a href="./../people/nambu_kojun.html">南武香淳</a></td></tr><tr><td style="text-align:left;"><strong>成立</strong></td><td style="text-align:left;">1996年公开成立</td></tr><tr><td style="text-align:left;"><strong>官方报刊</strong></td><td style="text-align:left;">《<a href="./../others/junshinri_newspaper.html">纯真理报</a>》</td></tr><tr><td style="text-align:left;"><strong>青年组织</strong></td><td style="text-align:left;"><a href="./../others/nambu_youth_league.html">爱南武为南武青年团</a></td></tr><tr><td style="text-align:left;"><strong>意识形态</strong></td><td style="text-align:left;"><a href="./rengoism.html">南武联合主义</a>、社会主义</td></tr><tr><td style="text-align:left;"><strong>政治立场</strong></td><td style="text-align:left;">极左翼激进派</td></tr><tr><td style="text-align:left;"><strong>官方色彩</strong></td><td style="text-align:left;">红色、黄色</td></tr><tr><td style="text-align:left;"><strong>官方口号</strong></td><td style="text-align:left;">“南武人，爱南武，为南武”</td></tr><tr><td style="text-align:left;"><strong>党歌</strong></td><td style="text-align:left;">《<a href="./../others/song_of_nambu.html">南武之歌</a>》</td></tr></tbody></table><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>南武联合党是南武一切事业的领导核心。它坚持<a href="./rengoism.html">联合主义</a>的指导地位，通过<a href="./comprehensive_leadership.html">全面领导制</a> 对国家的政治、经济、军事和文化等所有领域实施绝对领导。党的最终目标是克服修正主义，团结全体人民，建成伟大的<a href="./cyber_utopia.html">赛博乌托邦</a> 社会。</p><h2 id="简史" tabindex="-1">简史 <a class="header-anchor" href="#简史" aria-label="Permalink to “简史”">​</a></h2><ul><li><strong>1984-1996年</strong>：在创始人<a href="./../people/nambu_kojun.html">南武香淳</a> 同志的领导下，以地下组织的形式发起并领导了旨在团结劳动人民的<a href="./../others/worker_integration_movement.html">劳动者连带运动</a>。</li><li><strong>1996年</strong>：结束地下活动，向全社会公开宣告成立。</li><li><strong>1999年</strong>：领导发动伟大的<a href="./../others/progressive_revolution.html">南武进步革命</a> ，成功夺取政权，建立了<a href="./rengoist_republic_of_nambu.html">联合主义南武共和国</a>。</li></ul><h2 id="组织结构" tabindex="-1">组织结构 <a class="header-anchor" href="#组织结构" aria-label="Permalink to “组织结构”">​</a></h2><p>党的最高领导机构为<a href="./supreme_peoples_committee.html">南武最高人民委员会</a>，负责制定党的路线、方针和政策。</p><p>党的主要宣传喉舌为中央机关报《<a href="./../others/junshinri_newspaper.html">纯真理报</a>》，其官方青年后备军组织为<a href="./../others/nambu_youth_league.html">爱南武为南武青年团</a>。</p>',11)])])}const x=e(i,[["render",d]]);export{y as __pageData,x as default};
